 checked as (select *,case when oid is null then false when not arguments_complete then null when provariadic<>0 or array_position(input_names,null) is not null then null else argument_names <@ input_names and input_names[1:pronargs-pronargdefaults] <@ argument_names end as names_compatible from candidates)
